type Billing interface {                  // consumer-side delegate contract
    Charge(ctx context.Context, req ChargeRequest) (ChargeReply, error)
}
type billingHTTP struct{ hc *http.Client; base string }   // owns the transport
func (b *billingHTTP) Charge(ctx context.Context, req ChargeRequest) (ChargeReply, error) {
    body, err := json.Marshal(req)
    if err != nil { return ChargeReply{}, fmt.Errorf("billing encode: %w", err) }
    r, err := http.NewRequestWithContext(ctx, http.MethodPost, b.base+"/charge", bytes.NewReader(body))
    if err != nil { return ChargeReply{}, fmt.Errorf("billing request: %w", err) }
    resp, err := b.hc.Do(r)               // transport stays private
    if err != nil { return ChargeReply{}, fmt.Errorf("billing transport: %w", err) }
    defer resp.Body.Close()
    if resp.StatusCode < 200 || resp.StatusCode >= 300 {
        return ChargeReply{}, fmt.Errorf("billing: %w (%s)", ErrUnavailable, resp.Status)
    }
    var out ChargeReply
    if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
        return ChargeReply{}, fmt.Errorf("billing decode: %w", err)
    }
    return out, nil
}
